## Common Patterns

### 1. Sequential Processing Pipeline

```typescript
// Example: Remove background → Upscale → Restore
const processImage = async (imageUrl: string) => {
  // Step 1: Remove background
  const bgRemoved = await fetch('/api/ai/image/remove-bg', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify({ image: imageUrl })
  }).then(r => r.json());

  // Step 2: Upscale
  const upscaled = await fetch('/api/ai/image/upscale', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify({ image: bgRemoved.url, scale: 2 })
  }).then(r => r.json());

  // Step 3: Restore/enhance
  const restored = await fetch('/api/ai/image/restore', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify({ image: upscaled.url, fidelity: 0.7 })
  }).then(r => r.json());

  return restored.url;
};
```

### 2. Error Handling with Retry

```typescript
const callUtilityEndpoint = async (
  endpoint: string,
  payload: any,
  maxRetries: number = 2
): Promise<string> => {
  let lastError: Error | null = null;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(`/api/ai/image/${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error);
      }

      const data = await response.json();
      return data.url;
    } catch (error) {
      lastError = error as Error;
      if (attempt < maxRetries) {
        // Exponential backoff
        await new Promise(resolve =>
          setTimeout(resolve, Math.pow(2, attempt) * 1000)
        );
      }
    }
  }

  throw lastError;
};
```

### 3. Progress Tracking

```typescript
interface ProcessingStep {
  name: string;
  endpoint: string;
  payload: any;
}

const processWithProgress = async (
  steps: ProcessingStep[],
  onProgress: (percent: number, step: string) => void
) => {
  let currentUrl = steps[0].payload.image;

  for (let i = 0; i < steps.length; i++) {
    const step = steps[i];
    onProgress((i / steps.length) * 100, step.name);

    const response = await fetch(`/api/ai/image/${step.endpoint}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ ...step.payload, image: currentUrl })
    });

    const data = await response.json();
    currentUrl = data.url;
  }

  onProgress(100, 'Complete');
  return currentUrl;
};

// Usage
await processWithProgress([
  { name: 'Removing background', endpoint: 'remove-bg', payload: {} },
  { name: 'Upscaling', endpoint: 'upscale', payload: { scale: 2 } },
  { name: 'Restoring', endpoint: 'restore', payload: { fidelity: 0.7 } }
], (percent, step) => {
  console.log(`${step}: ${percent}%`);
});
```

### 4. Parallel Processing (Multiple Images)

```typescript
const processMultipleImages = async (
  imageUrls: string[],
  operation: 'remove-bg' | 'upscale' | 'outpaint' | 'restore',
  options: any = {}
) => {
  const promises = imageUrls.map(async (url) => {
    const response = await fetch(`/api/ai/image/${operation}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ image: url, ...options })
    });

    return response.json();
  });

  const results = await Promise.allSettled(promises);

  return results.map((result, index) => ({
    original: imageUrls[index],
    success: result.status === 'fulfilled',
    url: result.status === 'fulfilled' ? result.value.url : null,
    error: result.status === 'rejected' ? result.reason : null
  }));
};
```

