```

### 2. Rate Limit Management

```typescript
class RateLimitedQueue {
  private queue: Array<() => Promise<any>> = [];
  private processing = false;
  private requestsThisMinute = 0;
  private maxRequestsPerMinute = 30;

  async add<T>(fn: () => Promise<T>): Promise<T> {
    return new Promise((resolve, reject) => {
      this.queue.push(async () => {
        try {
          const result = await fn();
          resolve(result);
        } catch (error) {
          reject(error);
        }
      });
      this.process();
    });
  }

  private async process() {
    if (this.processing || this.queue.length === 0) return;
    if (this.requestsThisMinute >= this.maxRequestsPerMinute) {
      setTimeout(() => this.process(), 60000);
      return;
    }

    this.processing = true;
    this.requestsThisMinute++;

    const fn = this.queue.shift();
    if (fn) await fn();

    this.processing = false;
    setTimeout(() => this.process(), 2000); // 2s between requests
  }
}

// Usage
const queue = new RateLimitedQueue();
await queue.add(() => fetch('/api/ai/image/remove-bg', {...}));
```

### 3. Caching Processed Images

```typescript
const imageCache = new Map<string, string>();

const getCacheKey = (url: string, operation: string, options: any) => {
  return `${operation}:${url}:${JSON.stringify(options)}`;
};

const processWithCache = async (
  url: string,
  operation: string,
  options: any = {}
) => {
  const cacheKey = getCacheKey(url, operation, options);

  // Check cache first
  if (imageCache.has(cacheKey)) {
    console.log('[Cache] Hit:', cacheKey);
    return imageCache.get(cacheKey);
  }

  // Process image
  const response = await fetch(`/api/ai/image/${operation}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify({ image: url, ...options })
  });

  const data = await response.json();

  // Cache result
  imageCache.set(cacheKey, data.url);

  return data.url;
};
```

### 4. Model Selection Strategy

