// Usage
const model = selectModel('remove-bg', 'quality');
await fetch('/api/ai/image/remove-bg', {
  body: JSON.stringify({ image: url, model })
});
```

### 5. Input Validation

```typescript
const validateImageInput = (image: string): boolean => {
  // Check if it's a valid HTTPS URL
  if (image.startsWith('https://')) {
    try {
      new URL(image);
      return true;
    } catch {
      return false;
    }
  }

  // Check if it's a valid data URI
  if (image.startsWith('data:image/')) {
    const match = image.match(/^data:image\/(png|jpeg|jpg|webp);base64,/);
    return !!match;
  }

  // Check if it's valid base64
  try {
    atob(image.split(',').pop() || image);
    return true;
  } catch {
    return false;
  }
};

// Usage
if (!validateImageInput(imageUrl)) {
  throw new Error('Invalid image format');
}
```

